=(int)$b['id']?>" <?=(int)($s['branch_id']??0)===(int)$b['id']?'selected':''?>><?=h((string)$b['code'].' · '.(string)$b['name'])?></option><?php endforeach;?></select></label><label class="full">หมายเหตุ<input name="note" value="<?=h((string)($s['note']??''))?>" maxlength="200"></label></div><button class="secondary full-btn">บันทึกการแก้ไข</button></form><form method="post" onsubmit="return confirm('นำกะนี้ออกจากปฏิทิน? ระบบจะเก็บ Audit Log ไว้')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="cancel_shift"><input type="hidden" name="shift_id" value="<?=(int)$s['id']?>"><input type="hidden" name="pr_id" value="<?=$prId?>"><input type="hidden" name="date" value="<?=h($selectedDate)?>"><button class="danger full-btn">ลบกะนี้</button></form></div><?php endif;?></article><?php endforeach;?></section><section class="day-section"><div class="section-title"><h3>Attendance</h3><span><?=count($selectedAttendance)?> รายการ</span></div><?php if(!$selectedAttendance):?><div class="empty">ยังไม่มีการลงเวลาในวันนี้</div><?php endif;?><?php foreach($selectedAttendance as $a):?><article class="track-card"><div><small>CHECK-IN</small><b><?=h(date('H:i',strtotime((string)$a['check_in'])))?></b></div><div><small>CHECK-OUT</small><b><?=empty($a['check_out'])?'—':h(date('H:i',strtotime((string)$a['check_out'])))?></b></div><div><small>BRANCH</small><b><?=h(ps_branch_name($d,$a['branch_id']??null))?></b></div></article><?php endforeach;?></section><section class="day-section"><div class="section-title"><h3>Job Tracker</h3><span><?=count($selectedJobs)?> งาน</span></div><?php if(!$selectedJobs):?><div class="empty">ไม่มีงาน Assign ในวันนี้</div><?php endif;?><?php foreach($selectedJobs as $j):?><article class="job-card"><div><small><?=h((string)($j['ticket']??'JOB #'.$j['id']))?></small><b><?=h((string)($j['customer_name']??$j['guest_name']??'ลูกค้า'))?></b><span>โต๊ะ <?=h(ps_table_name($d,$j['table_id']??0))?></span></div><div class="job-state <?=h((string)($j['status']??'pending'))?>"><?=h(strtoupper((string)($j['status']??'pending')))?></div><div class="job-timeline"><span>Assign <?=!empty($j['assigned_at'])?h(date('H:i',strtotime((string)$j['assigned_at']))):'—'?></span><span>Accept <?=!empty($j['accepted_at'])?h(date('H:i',strtotime((string)$j['accepted_at']))):'—'?></span><span>Start <?=!empty($j['started_at'])?h(date('H:i',strtotime((string)$j['started_at']))):'—'?></span><span>Done <?=!empty($j['completed_at'])?h(date('H:i',strtotime((string)$j['completed_at']))):'—'?></span></div></article><?php endforeach;?></section><?php if($selectedLeaves):?><section class="day-section"><div class="section-title"><h3>Leave</h3><span><?=count($selectedLeaves)?> รายการ</span></div><?php foreach($selectedLeaves as $l):?><article class="leave-card"><b><?=h((string)($l['type']??'leave'))?></b><span><?=h((string)($l['reason']??''))?></span><em><?=h(strtoupper((string)($l['status']??'pending')))?></em></article><?php endforeach;?></section><?php endif;?></div></section>
